    return this;
}

public TEST_AtlSpecMD31ItemMasterRow withStatus(SJPMDInventImportStatus _status)
{
    this.parmExpectedFieldValue(fieldNum(SJPMDItemMaster, Status), _status);

    return this;
}

public TEST_AtlSpecMD31ItemMasterRow withErrorFlag(NoYes _errorFlag)
{
    this.parmExpectedFieldValue(fieldNum(SJPMDItemMaster, ErrorFlag), _errorFlag);

    return this;
}
